// ¿Armar un texto de a poco copia todo cada vez? Medimos cuánto tarda
function armar(n) {
  const t0 = performance.now();
  let s = "";
  for (let i = 0; i < n; i++) s += "x";
  return { largo: s.length, ms: Math.round(performance.now() - t0) };
}
console.log(armar(10000));
console.log(armar(100000));
console.log(armar(1000000));

