// Dos formatos INVENTADOS para el ejemplo (los reales tienen más casos):
//   código de envío: ENV-AAAA-NNNNNN       ej. ENV-2026-004471
//   teléfono móvil:  +54 9 AA NNNN-NNNN    ej. +54 9 11 5555-0123  (AA: código de área de 2 dígitos)
const codigoEnvio = /^ENV-\d{4}-\d{6}$/;
const telefono = /^\+54 9 (\d{2}) (\d{4})-(\d{4})$/;

const casos = [
  ["ENV-2026-004471", codigoEnvio],
  ["env-2026-004471", codigoEnvio],
  ["ENV-2026-4471", codigoEnvio],
  ["ENV-2026-004471 ", codigoEnvio],
  ["+54 9 11 5555-0123", telefono],
  ["+54 9 11 55550123", telefono],
  ["+54 9 351 555-0123", telefono],
];
for (const [texto, re] of casos) {
  console.log(JSON.stringify(texto).padEnd(24), re.test(texto));
}

