// Lo que hace src/util/texto.ts de Senda, adaptado: sin los tipos y con los rangos escritos como ̀-ͯ
const MAPA = { á:"a", à:"a", â:"a", ã:"a", ä:"a", å:"a", é:"e", è:"e", ê:"e", ë:"e", í:"i", ì:"i", î:"i", ï:"i",
  ó:"o", ò:"o", ô:"o", õ:"o", ö:"o", ú:"u", ù:"u", û:"u", ü:"u", ç:"c", ý:"y", ÿ:"y" };
const CON_TILDE = /[áàâãäåéèêëíìîïóòôõöúùûüçýÿ]/g;
const MARCAS = /[̀-ͯ]/g;

function sinTildes(t) {
  let s = t.toLowerCase().replace(CON_TILDE, (c) => MAPA[c] ?? c);   // 1) el mapa explícito hace el trabajo
  s = s.replace(/ñ/g, "\u0001").normalize("NFD").replace(MARCAS, "").replace(/\u0001/g, "ñ");  // 2) red de seguridad
  return s;                                                         // la ñ se protege: es otra letra
}
const plegar = (t) => sinTildes(t).replace(/ñ/g, "n");              // versión de búsqueda: la ñ también pasa a n

// Un buscador de localidades (lista inventada para el ejemplo)
const lugares = ["Córdoba", "Neuquén", "Añelo", "Ñuñoa", "Mendoza", "Tucumán", "San Nicolás"];
const buscar = (consulta, f) => lugares.filter(l => f(l).includes(f(consulta)));
console.log("sin tratar:   «cordoba» →", JSON.stringify(buscar("cordoba", x => x)));
console.log("sinTildes:    «CORDOBA» →", JSON.stringify(buscar("CORDOBA", sinTildes)));
console.log("sinTildes:    «anelo»   →", JSON.stringify(buscar("anelo", sinTildes)));
console.log("plegar:       «anelo»   →", JSON.stringify(buscar("anelo", plegar)));
console.log("sinTildes de «Canción»:", sinTildes("Canción"), "| de «ñandú»:", sinTildes("ñandú"), "| plegar de «ñandú»:", plegar("ñandú"));

// Un texto puede llegar en las dos formas (NFC o NFD) y no ser igual a primera vista
const a = "Neuquén", b = "Neuquén";
console.log(a === b, a.length, b.length, a.normalize("NFC") === b.normalize("NFC"));
console.log(sinTildes(a) === sinTildes(b));

// La cadena de limpieza de la búsqueda de la Biblia de Senda: deja solo letras, números y espacios, y parte en palabras
const normalizar = (s) => plegar(s).replace(/[^a-z0-9ñ ]/g, " ");
