// Dos validadores del campo «observaciones»: palabras de letras y números, separadas por un espacio
const fragil = /^(\w+\s?)*$/;      // un grupo que se repite, con algo repetible adentro
const seguro = /^\w+(\s\w+)*$/;    // acepta casi lo mismo, sin que una misma letra se pueda repartir de dos maneras

const entrada = n => "a".repeat(n) + "!";    // casi válida: falla recién en el último carácter
const medir = (re, n) => {
  const t0 = performance.now();
  const r = re.test(entrada(n));
  return { r, ms: Math.round(performance.now() - t0) };
};

console.log("con texto normal:", fragil.test("ent 4471 ok"), seguro.test("ent 4471 ok"));
for (let n = 16; n <= 30; n += 2) {
  const a = medir(fragil, n);
  console.log("n =", n, "| frágil:", a.ms, "ms | seguro:", medir(seguro, n).ms, "ms");
  if (a.ms > 300) { console.log("corto acá: el paso siguiente tardaría cerca de 4 veces más"); break; }
}
console.log("seguro con 100000 letras:", medir(seguro, 100000).ms, "ms");
